"""Exercise selected-section reads as ai_reader against Rails-generated target digests."""

import json
from pathlib import Path
from uuid import UUID

import pytest

from database.library_review_reader import read_library_review
from tests import test_career_library_reader as database_fixtures
from tests.test_career_library_reader import _insert, _insert_user

admin_connection = database_fixtures.admin_connection

pytestmark = pytest.mark.db


def test_owned_sections_match_rails_targets_with_dates_unicode_and_html(admin_connection):
    # Golden targets were generated by the real Rails ReviewSnapshot/ReviewCommand
    # admission path. Keep the dates, nulls, HTML and Unicode separator in this contract.
    fixture = json.loads((Path(__file__).parent / "fixtures/library_review_targets.json").read_text())
    user_id = UUID(fixture["user_id"])
    targets = fixture["targets"]
    role_id = targets["experience"][0]["record_id"]
    highlight_id = targets["experience"][1]["record_id"]
    project_id = targets["projects"][0]["record_id"]
    context_id = targets["career_contexts"][0]["record_id"]
    admin_connection.execute("INSERT INTO users (id,email,summary,created_at,updated_at) VALUES (%s,%s,%s,now(),now())",
                             (user_id, "review-contract@example.test", "Résumé <&> engineer"))
    admin_connection.execute("""INSERT INTO experiences
        (id,user_id,company,title,location,start_date,description,created_at,updated_at)
        VALUES (%s,%s,'A&B','Engineer','Manila','2020-01-02',%s,now(),now())""",
                             (role_id, user_id, "Built <tools> \u2028"))
    admin_connection.execute("""INSERT INTO experience_highlights (id,experience_id,content,created_at,updated_at)
        VALUES (%s,%s,%s,now(),now())""", (highlight_id, role_id, "Delivered résumé tools"))
    admin_connection.execute("""INSERT INTO projects (id,user_id,name,role,start_date,description,created_at,updated_at)
        VALUES (%s,%s,'Tool','Developer','2021-02-03','Made tools',now(),now())""", (project_id, user_id))
    admin_connection.execute("""INSERT INTO career_contexts (id,user_id,requirement,response,created_at,updated_at)
        VALUES (%s,%s,'Tools','Built tools',now(),now())""", (context_id, user_id))
    other_user = _insert_user(admin_connection, summary="Foreign summary")
    foreign_role = _insert(admin_connection, "experiences", user_id=other_user, company="Foreign", title="Private")
    _insert(admin_connection, "experience_highlights", experience_id=foreign_role, content="Foreign highlight")
    _insert(admin_connection, "projects", user_id=other_user, name="Foreign project", description="Private")
    _insert(admin_connection, "career_contexts", user_id=other_user, requirement="Foreign", response="Private")
    admin_connection.execute("SET LOCAL ROLE ai_reader")

    for section, expected in targets.items():
        actual = read_library_review(admin_connection, user_id, section)
        assert [target.model_dump() for target in actual.targets] == expected
        assert "Foreign" not in actual.library.model_dump_json()
        assert not actual.library.educations and not actual.library.skills
        if section != "experience":
            assert not actual.library.experiences
        if section != "summary":
            assert not actual.library.summary
        if section != "projects":
            assert not actual.library.projects
        if section != "career_contexts":
            assert not actual.library.career_contexts
